public static URL appendTrailingSlash(URL url) {

String file;
file = url.getFile();
if (file.endsWith("/")) {
return url;
}
try {
return new URL(url.getProtocol(), url.getHost(), url.getPort(), file + "/");
}
catch (MalformedURLException e) {
Assert.isTrue(!true, Policy.bind("assert.internalError"));
}

return null;
}
